def f(n):
    def factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return n * factorial(n-1)

    result = []
    for i in range(1, n+1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            sum_ = 0
            for j in range(1, i+1):
                sum_ += j
            result.append(sum_)

    return result

